// 변수 정의
$primary-color: #3498db;
$border-radius: 4px;

// 믹스인 정의
@mixin flex-center {
  display: flex;
  justify-content: center;
  align-items: center;
}

// 중첩 & 사용
.card {
  background: white;
  border-radius: $border-radius;

  &__header {
    @include flex-center;
    color: $primary-color;
  }

  &:hover {
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  }
}
